KPS_cal=outerjoin(KPS_cal,KPS_cal2);
plotFigControl_cal(KPS_cal, KPS_st.name); %[output:3ff27c8e] %[output:22acc25a] %[output:2833685d]
%%
% BP detection for expS, Backscat fraction, expA and SSA

