T_KPS_expA_BP=make_table_breakpoints_def(break_KPS_expA_BP);

names_BbF={'BbsFG'};
break_KPS_BbF_BP=change_point_analysis_Def(KPS_cal,names_BbF,0.05,'KPS','backscat fraction'); %[output:9599b3d3] %[output:2db9d923]
T_KPS_BbF_BP=make_table_breakpoints_def(break_KPS_BbF_BP);

names_SSA={'SSA211'};
